head.script:
// 재현 조건(Jira 첨부 샘플): 창·팝업 onpageload 에서 즉시 executeSubmission
scwin.onpageload = function() {
	scwin.trigger2_onclick();
};

scwin.trigger2_onclick = function(e) {
	$p.executeSubmission("submission1");
};

scwin.trigger3_onclick = function(e) {
	if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
	var rowJSON = {
		"Personal Info": {
			"Name": "Lee",
			"Age": 50,
			"Married": false
		},
		"Region": "Seoul",
		"Carrier": true
	};
	var dataObject = {
		"type": "json",
		"name": "paramTest",
		"data": rowJSON
	};
	var options = {
		id: "popup1",
		type: "wframePopup",
		width: "400px",
		height: "300px",
		top: "130px",
		left: "200px",
		popupName: "테스트 팝업",
		modal: false,
		resizable: true,
		status: true,
		menubar: false,
		scrollbars: false,
		dataObject: dataObject,
		title: "false",
		processMsgFrame: "true"
	};
	$p.openPopup("/sample/common_link/windowContainer_processMsgFrame_WESD-612_(WSQ-4699)_sub.xml", options);
};
